                              className="w-8 h-8 flex items-center justify-center hover:bg-white/20 rounded-full transition-colors"
                            >
                              <Plus size={14} strokeWidth={3} />
                            </button>
                          </motion.div>
                        ) : (
                          <motion.button
                            key="add"
                            layout
                            initial={{ opacity: 0, scale: 0.8 }}
                            animate={{ opacity: 1, scale: 1 }}
                            whileTap={{ scale: 0.9 }}
                            onClick={() => updateCart(product.id, 1)}
                            className="w-10 h-10 bg-primary text-white flex items-center justify-center rounded-full shadow-lg shadow-primary/20 hover:shadow-primary/40 transition-all"
                          >
                            <Plus size={22} strokeWidth={3} />
                          </motion.button>
                        )}
                      </AnimatePresence>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </section>

        <div className="h-20 flex flex-col items-center justify-center opacity-30">
          <Info size={18} className="mb-2" />
          <p className="text-[10px] font-bold uppercase tracking-[0.3em]">End of Menu</p>
        </div>
      </main>

      {/* BOTTOM NAVIGATION */}
      <nav className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[92%] max-w-[440px] bg-slate-900/95 backdrop-blur-2xl rounded-[32px] p-2 flex items-center justify-between shadow-2xl z-[100]">
        {[
          { id: 'home', icon: Home, label: 'Home' },
          { id: 'categories', icon: LayoutGrid, label: 'Browse' },
          { id: 'offers', icon: Tag, label: 'Deals' },
          { id: 'cart', icon: ShoppingBag, label: 'Cart', count: Object.values(cart).reduce((a, b) => a + b, 0) },
        ].map((item) => {
          const isActive = item.id === 'home';
          return (
            <motion.button
              key={item.id}
              whileTap={{ scale: 0.9 }}
              className={`relative flex items-center gap-2.5 px-5 py-3.5 rounded-[24px] transition-all duration-300 ${
                isActive ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              <item.icon size={20} strokeWidth={isActive ? 3 : 2} />
              {isActive && (
                <motion.span 
                  initial={{ width: 0, opacity: 0 }}
                  animate={{ width: 'auto', opacity: 1 }}
                  className="text-xs font-bold tracking-tight"
                >
                  {item.label}
                </motion.span>
              )}
              {item.count > 0 && !isActive && (
                <span className="absolute top-2 right-3 w-4 h-4 bg-primary text-white text-[8px] font-black rounded-full flex items-center justify-center border border-slate-900">
                  {item.count}
                </span>
              )}
            </motion.button>
          );
        })}
      </nav>

      {/* TEXTURE OVERLAY */}
      <div className="fixed inset-0 pointer-events-none z-[200]">
        <div className="w-full h-full opacity-[0.02] bg-[url('https://www.transparenttextures.com/patterns/asfalt-dark.png')]" />
      </div>
    </div>
  );
};

export default App;
